#!/usr/bin/env tsx
// Cyrus docs generator (r46). Builds the REFERENCE pages of docs/cyrus/ straight from the code, with zero model tokens:
// flags/settings/env, routes, DB tables, version registry, adapters + capability matrix, OpenAPI operations,
// feature -> flag -> doc map, module map, scripts and test inventory.
//
//   npx tsx scripts/cyrus/docs-build.ts            write docs/cyrus/reference/*.md
//   npx tsx scripts/cyrus/docs-build.ts --check    exit 1 when a committed page is stale (what test/cyrus-docs-coverage.test.ts does)
//
// Rules: deterministic (no dates, no absolute paths, sorted), read-only on the code, never prints a secret value (it only
// records NAMES of env vars/settings and, for defaults, the literal fallback written next to the name in code).
// The hand-written narrative pages (00..14) are NOT touched; see docs/cyrus/14-how-to-work-here.md "docs update checklist".
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { ADAPTERS } from "../../lib/cyrus/adapters";
import { CYRUS_GAMES } from "../../lib/cyrus/games";
import { CYRUS_ENV_FLAGS } from "../../lib/cyrus/admin/flags";
