/** Repo root = the nearest ancestor of the working directory that has prisma/schema.prisma (works under tsx CJS and ESM). */
function findRoot(start: string): string {
  let d = start;
  for (let i = 0; i < 8; i++) {
    if (existsSync(path.join(d, "prisma", "schema.prisma")) && existsSync(path.join(d, "scripts", "cyrus"))) return d;
    const up = path.dirname(d);
    if (up === d) break;
    d = up;
  }
  throw new Error("docs-build: run from inside the repo (prisma/schema.prisma not found above " + start + ")");
}
export const ROOT = findRoot(process.cwd());
export const REF_DIR = "docs/cyrus/reference";

const SCAN_ROOTS = ["lib", "app", "components", "services", "worker", "scripts", "deploy", "platform", "apps", "middleware.ts", "next.config.ts", "instrumentation.ts", "tools"];
const SKIP_DIRS = new Set(["node_modules", ".next", ".git", "dist", "build", "test", "__snapshots__", ".cyrus-local", "fixtures"]);
const CODE_EXT = /\.(ts|tsx|js|mjs|cjs|sh|service|yml|yaml)$/;

const rd = (rel: string) => readFileSync(path.join(ROOT, rel), "utf8");
const exists = (rel: string) => existsSync(path.join(ROOT, rel));
const cell = (s: unknown) => String(s ?? "").replace(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g, "<ip>").replace(/\b[a-f0-9]{40,}\b/g, "<hash>").replace(/\|/g, "¦").replace(/\r?\n/g, " ").trim();
const code = (s: string) => (s ? "`" + s.replace(/`/g, "'") + "`" : "");

function walk(rel: string, out: string[] = []): string[] {
  const abs = path.join(ROOT, rel);
  if (!existsSync(abs)) return out;
  const st = statSync(abs);
  if (st.isFile()) {
    if (CODE_EXT.test(rel) && !/\.test\.(ts|tsx)$/.test(rel) && !/\.d\.ts$/.test(rel)) out.push(rel);
    return out;
  }
  for (const n of readdirSync(abs).sort()) {
    if (SKIP_DIRS.has(n) || n.startsWith(".")) continue;
    walk(rel + "/" + n, out);
  }
  return out;
}

let FILES_CACHE: string[] | null = null;
function allFiles(): string[] {
  if (!FILES_CACHE) FILES_CACHE = SCAN_ROOTS.flatMap((r) => walk(r)).sort();
  return FILES_CACHE;
}

