// ---------- flags / settings / env ----------
export type NameKind = "env" | "setting";
export type NameRow = { name: string; kind: NameKind; files: string[]; defaultHint: string; doc: string };

const ENV_TOKEN = /\b(CYRUS_[A-Z0-9_]+|MB_[A-Z0-9_]+)\b/g;
const SETTING_TOKEN = /["'](cyrus_[a-z0-9_]+)["']/g;

/** A CYRUS_/MB_ token counts as an env var/flag only where it is used as a string/env reference, not as a TS identifier. */
function envUses(text: string, rel: string): Set<string> {
  const found = new Set<string>();
  const shell = /\.(sh|service|yml|yaml)$/.test(rel) || /Dockerfile/.test(rel);
  for (const m of text.matchAll(/process\.env\.([A-Z][A-Z0-9_]*)|process\.env\[\s*["']([A-Z][A-Z0-9_]*)["']\s*\]|["']((?:CYRUS|MB)_[A-Z0-9_]+)["']|`((?:CYRUS|MB)_[A-Z0-9_]+)`|\benv\.((?:CYRUS|MB)_[A-Z0-9_]+)\b/g)) {
    const n = m[1] ?? m[2] ?? m[3] ?? m[4] ?? m[5];
    if (n && (/^(CYRUS|MB)_/.test(n))) found.add(n);
  }
  if (shell) for (const m of text.matchAll(ENV_TOKEN)) found.add(m[1]);
  // names written inside prose comments of a file that also configures them are caught by the quoted forms above
  return found;
}

function otherEnv(text: string): Set<string> {
  const found = new Set<string>();
  for (const m of text.matchAll(/process\.env\.([A-Z][A-Z0-9_]*)|process\.env\[\s*["']([A-Z][A-Z0-9_]*)["']\s*\]/g)) {
    const n = m[1] ?? m[2];
    if (n && !/^(CYRUS|MB)_/.test(n)) found.add(n);
  }
  return found;
}

function firstLineOf(text: string, token: string): { line: number; lines: string[] } | null {
  const lines = text.split("\n");
  const i = lines.findIndex((l) => l.includes(token));
  return i < 0 ? null : { line: i, lines };
}

