    new RegExp(`process\\.env\\[\\s*["']${esc}["']\\s*\\]\\s*(?:\\?\\?|\\|\\|)\\s*("[^"\\n]{0,60}"|'[^'\\n]{0,60}'|-?\\d[\\d._]*|true|false)`),
    new RegExp(`(?:env\\w*|int\\w*|bool\\w*|num\\w*|getSetting\\w*|setting\\w*)\\(\\s*["']${esc}["']\\s*,\\s*("[^"\\n]{0,60}"|'[^'\\n]{0,60}'|-?\\d[\\d._]*|true|false)`),
    new RegExp(`\\$\\{${esc}:-([^}]{0,40})\\}`),
